import dataUrl from './frequencies-data.json?url';

// Radio frequencies published for an airport (ATIS, clearance, ground,
// tower, approach, departure, CTAF), for the airport card.
//
// frequencies-data.json is generated by scripts/build-frequencies.py from
// OurAirports (public domain): civil VHF channels only, in the order a
// flight meets them. Regenerate, do not hand-edit. Fetched the first time
// an airport card opens.

export interface Frequency {
  /** 'ATIS', 'GND', 'TWR', 'APP', ... as OurAirports types them. */
  kind: string;
  /** What the channel is called when that says more than the type; else ''. */
  name: string;
  mhz: number;
}

/** Parse the generated file: ICAO code → frequencies. Rows that do not fit are dropped. */
export function decodeFrequencies(raw: unknown): Map<string, Frequency[]> {
  const out = new Map<string, Frequency[]>();
  const table = (raw as { frequencies?: unknown } | null)?.frequencies;
  if (!table || typeof table !== 'object') return out;
  for (const [icao, rows] of Object.entries(table as Record<string, unknown>)) {
    if (!Array.isArray(rows)) continue;
    const list: Frequency[] = [];
    for (const row of rows as unknown[]) {
      if (!Array.isArray(row)) continue;
      const [kind, name, mhz] = row as unknown[];
      if (typeof kind === 'string' && typeof name === 'string' && typeof mhz === 'number' && Number.isFinite(mhz)) {
        list.push({ kind, name, mhz });
      }
    }
    if (list.length > 0) out.set(icao, list);
  }
  return out;
}

/** "123.675", "121.8": at least one decimal, no more than the channel needs. */
export function formatMhz(mhz: number): string {
  const text = mhz.toFixed(3).replace(/0+$/, '');
  return text.endsWith('.') ? `${text}0` : text;
}

let table: Map<string, Frequency[]> | null = null;
let loading: Promise<void> | null = null;

/** Frequencies of one airport; empty when it has none on file. Resolves empty if the data cannot be fetched. */
export async function frequenciesOf(icao: string): Promise<readonly Frequency[]> {
  if (!table) {
    loading ??= fetch(dataUrl)
      .then((res) => {
        if (!res.ok) throw new Error(`frequency data: HTTP ${res.status}`);
        return res.json() as Promise<unknown>;
      })
      .then((raw) => {
        table = decodeFrequencies(raw);
      })
      .catch((err: unknown) => {
        console.warn('[frequencies] could not load', err);
        loading = null;
      });
    await loading;
  }
  return table?.get(icao) ?? [];
}
